/**
 * The worklet sources, inlined into the generated page by build-editor.mjs
 * (the `__WORKLET__` / `__REVERB__` markers in the template) before the app
 * bundle runs. The host turns them into blob URLs for `FmEngine.init`.
 */
interface Window {
  __A204_DSP__: { fm: string; reverb: string };
}
